import argparse
from pathlib import Path

from fishing_audio_templates import generate, read


def main():
    parser = argparse.ArgumentParser(description="Generate the bag warning spectral template.")
    parser.add_argument("input", type=Path)
    parser.add_argument("header", type=Path)
    args = parser.parse_args()
    templates, _ = generate([read(args.input)])
    rows = [", ".join(f"{value:.8f}f" for value in row) for row in templates[0]]
    data = ",\n".join("    {" + row + "}" for row in rows)
    args.header.write_text(
        '// Generated by scripts/generate_bag_audio_template.py.\n#pragma once\n'
        '#include "audio_match_reference.h"\n'
        'namespace paxg::audio::reference {\n'
        'inline constexpr float bagThreshold = 0.90f;\n'
        'inline constexpr float bagTemplate[frames][bands] = {\n'
        + data + '\n};\n}\n', encoding="utf8")


if __name__ == "__main__":
    main()
